import{_ as o,l as i,o as e,c as l,v as t,p as n,x as s,d as S,i as d,S as T}from"./chunks/framework.InCnrqk-.js";const H=JSON.parse('{"title":"HSTS 与钉扎对照","description":"","frontmatter":{"title":"HSTS 与钉扎对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hsts.md","filePath":"cs/hsts.md","lastUpdated":1789023840000}'),h={name:"cs/hsts.md"};function p(c,a,A,_,E,m){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="hsts-与钉扎对照" tabindex="-1">HSTS 与钉扎对照 <a class="header-anchor" href="#hsts-与钉扎对照" aria-label="Permalink to &quot;HSTS 与钉扎对照&quot;">​</a></h1><div class="epigraph"><p>HSTS 让浏览器记住「该主机只走 HTTPS」，减少第一次明文被劫持成假站点的窗口；钉扎则把信任锚收得更窄，失败模式也更硬。</p><footer>—— 据 RFC 6797 HSTS；Anderson 对钉扎与 PKI 的整理；对照 RFC 8446</footer></div><p><a href="/cs/mitm">上一课</a>说明未认证的加密等于与中间人建了两条会话。本课不重做假冒几何。缺口是浏览器的第一次访问：用户敲 <code>http://</code>，或被降级。HSTS 用响应头声明只 HTTPS 及期限。证书钉扎对照：只接受某公钥。DoS 下一课打的是 A 轴。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>中间人课留下「证书关掉缺口」。用户与书签仍可能走 80 端口。<a href="/cs/http-tls-entry">TLS 入口</a> 假定已经在 TLS 上。HSTS：浏览器为该名字存「强制 HTTPS」，连内部链也升级。预加载列表把第一次访问也收进已知集。钉扎：额外约束叶子或中间 CA，CA 误签也不收——但钉错则自毁访问。缺口是<strong>客户端政策补 PKI</strong>。</p><p><span class="marginnote">HSTS 不修错误的证书链，只修协议降级与明文入口。钉扎在浏览器里已大幅收缩，对照即可，不把已废弃的 HPKP 细节当现行主干。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>服务器在 HTTPS 响应里声明 max-age。客户端之后拒绝明文与未认证升级。防御降级：不接受「这次用弱套件」。钉扎若用，必须有备份键与过期，否则运维事故变成全局不可用。本课不写如何伪造证书。</p>',8)),(e(),n(T,null,{default:s(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HTTP%5B%22%E6%98%8E%E6%96%87%E5%85%A5%E5%8F%A3%22%5D%20--%3E%20HSTS%5B%22%E8%AE%B0%E4%BD%8F%E5%8F%AA%20HTTPS%22%5D%0A%20%20HSTS%20--%3E%20TLS%5B%22%E5%BC%BA%E5%88%B6%E6%8F%A1%E6%89%8B%20RFC%208446%22%5D%0A%20%20PIN%5B%22%E9%92%89%E6%89%8E%22%5D%20--%3E%20NARROW%5B%22%E6%9B%B4%E7%AA%84%E9%94%9A%E3%80%81%E6%9B%B4%E7%A1%AC%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[S(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>HSTS 把用户的第一次明文窗口缩小，服务真实性与保密的入口一致性。它依赖一次真实的 HTTPS 才能种下策略（或预加载）。中间人若在种策略前就在路径上，HSTS 尚未生效——预加载是补丁。后课 DoS 不靠假证书，靠资源耗尽。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部浏览器 UI 锁图标史写进主干。可用如何被洪水与放大打穿，下一课。</p><p>后课默认：站点可要求客户端拒绝明文。CIA 的 A 仍可单独失败。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HSTS 强制后续只走 HTTPS，缩小降级窗口。</li><li>钉扎更窄更脆，仅作对照。</li><li>DoS 与放大下一课。</li><li>出处：RFC 6797；Anderson；RFC 8446。</li></ul>',7))])}const u=o(h,[["render",p]]);export{H as __pageData,u as default};
